    "question": "Evaluate the following four statements concerning the Lac Operon:\n(A) In the absence of lactose, the repressor binds the operator and prevents transcription.\n(B) The inducer for the lac operon is glucose.\n(C) Gene z codes for beta-galactosidase which cleaves lactose into glucose and galactose.\n(D) Permease increases the cell membrane permeability to beta-galactosides.\nWhich of the above statements are CORRECT?",
