    "correctAnswer": "D",
    "correctOption": "D",
    "correctIndex": 3,
    "explanation": "1. CONCEPT:\nForensic VNTR matching interpretation.\n\n2. STEP-BY-STEP SOLUTION:\nDNA fingerprinting requires complete multi-locus band concordance across all tested VNTR loci for positive individual identification. Suspect 1 matches 100% of bands, confirming identity. A partial match (50%) in Suspect 2 excludes him as the donor (it may indicate a relative).\n\n3. FINAL ANSWER:\nOption D: Suspect 1 is the individual who left the crime scene stain; Suspect 2 is excluded as the direct donor\n\n4. WHY OTHER OPTIONS ARE WRONG:\nPartial matches exclude rather than identify individual suspects.",
    "solutionStructured": {
      "concept": "Forensic VNTR matching interpretation.",
      "stepByStep": "DNA fingerprinting requires complete multi-locus band concordance across all tested VNTR loci for positive individual identification. Suspect 1 matches 100% of bands, confirming identity. A partial match (50%) in Suspect 2 excludes him as the donor (it may indicate a relative).",
      "finalAnswer": "Option D: Suspect 1 is the individual who left the crime scene stain; Suspect 2 is excluded as the direct donor",
      "whyOtherOptionsWrong": "Partial matches exclude rather than identify individual suspects."
    },
