    "question": "A double-stranded DNA segment is transcribed into mRNA. The sequence of the CODING strand of this transcription unit is:\n5' - ATGCGATTCGAT - 3'\nWhat is the exact sequence of the mRNA transcript synthesized from this transcription unit?",
    "options": {
      "A": "3' - UACGCUAAGCUA - 5'",
      "B": "5' - UACGCUAAGCUA - 3'",
      "C": "3' - AUGCGAUUCGAU - 5'",
      "D": "5' - AUGCGAUUCGAU - 3'"
    },
