    "question": "A forensic investigation compares DNA from a crime scene semen stain with blood DNA from two suspects (Suspect 1 and Suspect 2) using Southern blot VNTR fingerprinting across four distinct chromosomal loci (A, B, C, D). The semen stain displays band sizes at 4.2 kb, 6.8 kb, 8.5 kb, and 11.2 kb. Suspect 1 matches at all four loci, whereas Suspect 2 matches at only two loci. What is the definitive forensic conclusion?",
