    "id": "molecular-basis-inheritance-mcq-466",
    "questionNumber": 466,
    "question": "A synthetic mRNA sequence has the following sequence: 5' - AUG UUU UUU UAA UUU - 3'. In a cell-free translation system, how many amino acids will be present in the resulting polypeptide chain?",
    "options": {
      "A": "3 amino acids (Methionine - Phenylalanine - Phenylalanine)",
      "B": "5 amino acids",
      "C": "1 amino acid",
      "D": "4 amino acids"
    },
    "optionsList": [
      "3 amino acids (Methionine - Phenylalanine - Phenylalanine)",
      "5 amino acids",
      "1 amino acid",
      "4 amino acids"
    ],
    "correctAnswer": "A",
    "correctOption": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nTranslation reading frame and termination.\n\n2. STEP-BY-STEP SOLUTION:\nCodon 1: AUG -> Methionine. Codon 2: UUU -> Phenylalanine. Codon 3: UUU -> Phenylalanine. Codon 4: UAA -> STOP codon. Translation terminates immediately at UAA, and the downstream codon (UUU) is never translated. The polypeptide contains exactly 3 amino acids.\n\n3. FINAL ANSWER:\nOption A: 3 amino acids (Methionine - Phenylalanine - Phenylalanine)\n\n4. WHY OTHER OPTIONS ARE WRONG:\nDownstream codons after a stop codon are not translated.",
    "solutionStructured": {
      "concept": "Translation reading frame and termination.",
      "stepByStep": "Codon 1: AUG -> Methionine. Codon 2: UUU -> Phenylalanine. Codon 3: UUU -> Phenylalanine. Codon 4: UAA -> STOP codon. Translation terminates immediately at UAA, and the downstream codon (UUU) is never translated. The polypeptide contains exactly 3 amino acids.",
      "finalAnswer": "Option A: 3 amino acids (Methionine - Phenylalanine - Phenylalanine)",
      "whyOtherOptionsWrong": "Downstream codons after a stop codon are not translated."
    },
