    "id": "molecular-basis-inheritance-mcq-487",
    "questionNumber": 487,
    "question": "A mutant strain of E. coli has a non-sense mutation in the lac z gene that causes premature termination of translation after 20 amino acids. If this bacterial strain is cultured in a medium containing lactose as the sole carbon source, what will be the physiological outcome?",
    "options": {
      "A": "The bacteria will grow twice as fast because energy is conserved",
      "B": "The bacteria will synthesize cellulose instead of glucose",
      "C": "The bacteria will fail to grow because functional beta-galactosidase is absent, preventing the hydrolysis of lactose into glucose and galactose",
      "D": "The bacteria will convert into eukaryotic cells"
    },
    "optionsList": [
      "The bacteria will grow twice as fast because energy is conserved",
      "The bacteria will synthesize cellulose instead of glucose",
      "The bacteria will fail to grow because functional beta-galactosidase is absent, preventing the hydrolysis of lactose into glucose and galactose",
      "The bacteria will convert into eukaryotic cells"
    ],
    "correctAnswer": "C",
    "correctOption": "C",
    "correctIndex": 2,
    "explanation": "1. CONCEPT:\nLac operon loss-of-function mutation.\n\n2. STEP-BY-STEP SOLUTION:\nA non-functional truncated beta-galactosidase cannot hydrolyze lactose. Since lactose cannot be metabolized into glucose and galactose, the cell starves and cannot grow on lactose as the sole carbon source.\n\n3. FINAL ANSWER:\nOption C: The bacteria will fail to grow because functional beta-galactosidase is absent, preventing the hydrolysis of lactose into glucose and galactose\n\n4. WHY OTHER OPTIONS ARE WRONG:\nWithout beta-gal, lactose cannot be utilized.",
    "solutionStructured": {
      "concept": "Lac operon loss-of-function mutation.",
      "stepByStep": "A non-functional truncated beta-galactosidase cannot hydrolyze lactose. Since lactose cannot be metabolized into glucose and galactose, the cell starves and cannot grow on lactose as the sole carbon source.",
      "finalAnswer": "Option C: The bacteria will fail to grow because functional beta-galactosidase is absent, preventing the hydrolysis of lactose into glucose and galactose",
      "whyOtherOptionsWrong": "Without beta-gal, lactose cannot be utilized."
    },
